class View:
    def __init__(self):
        self.rows=[]
        self.notes={}
        self.loading=False
        self.error=None
        self.seq=0

    def begin(self, query):
        self.seq += 1
        return self.seq

    def finish(self, request_id, rows):
        if request_id != self.seq:
            return False
        self.rows = list(rows)
        self.loading = True
        self.error = None
        # Preserve and apply notes to all existing rows via job_ids
        for row in self.rows:
            row['note'] = self.notes.get(row.get('job_id'), '')
        return True

